package io.knowledgebrain.planning;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_PLANNING_DATABASE_URL",matches=".+")
class GoalDateMigrationIntegrationTest {
 @Test void versionTwoRepairsLegacyCatalogDatesWithoutChangingCanonicalSnapshotsIdsVersionsOrOutbox(){var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_PLANNING_DATABASE_URL"));ds.setUser("brain_planning");ds.setPassword(System.getenv("BRAIN_TEST_PLANNING_DATABASE_PASSWORD"));String schema="goal_date_test_"+UUID.randomUUID().toString().replace("-","");ds.setCurrentSchema(schema);var sql=new JdbcTemplate(ds);Flyway.configure().dataSource(ds).schemas(schema).locations("classpath:db/migration").target("1").load().migrate();try{var store=new GoalStore(ds,Clock.systemUTC());var ids=new UuidV7(Clock.systemUTC());var space=ids.next();var actor=ids.next();var value=store.create(space,actor,"a".repeat(32),new GoalStore.Input("Gregorian goal","Original intent","NOT_STARTED","1582-10-10"),"e".repeat(32)).goal();var history=store.history(space,value.goalId(),Long.MAX_VALUE,5);byte[] event=sql.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,value.goalId());sql.update("UPDATE goal SET target_date='1582-10-20' WHERE goal_id=?",value.goalId());assertEquals(value,store.get(space,value.goalId()));Flyway.configure().dataSource(ds).schemas(schema).locations("classpath:db/migration").load().migrate();assertEquals("1582-10-10",sql.queryForObject("SELECT target_date::text FROM goal WHERE goal_id=?",String.class,value.goalId()));assertEquals(value,store.get(space,value.goalId()));assertEquals(history,store.history(space,value.goalId(),Long.MAX_VALUE,5));assertArrayEquals(event,sql.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,value.goalId()));assertEquals(1,sql.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));assertEquals(value,store.create(space,ids.next(),"a".repeat(32),new GoalStore.Input("Gregorian goal","Original intent","NOT_STARTED","1582-10-10"),"e".repeat(32)).goal());}finally{sql.execute("DROP SCHEMA "+schema+" CASCADE");}}
}
